 $save(['fields'=>['title'=>'Warm Way Home','lyrics'=>'현재 가사','sunoPrompt'=>'warm piano pop','vocal'=>'남녀듀엣']]);
 foreach([[],['title','title'],['sunoUrl'],['unknown'],[42]] as $keys)denied(fn()=>ncd_target_keys($keys),'invalid_targets');
